<?php
require_once 'config.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0; $stmt=$conn->prepare("SELECT e.*, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='confirmed') AS registered FROM events e WHERE e.id=?"); $stmt->bind_param('i',$id); $stmt->execute(); $event=$stmt->get_result()->fetch_assoc(); if(!$event){http_response_code(404);$page_title='Event not found';include 'includes/header.php';echo '<main class="page-shell"><h1>Event not found</h1><a href="index.php">Back to events</a></main>';include 'includes/footer.php';exit;}
$page_title=$event['title'];include 'includes/header.php';$remaining=max(0,(int)$event['capacity']-(int)$event['registered']); ?>
<main class="page-shell"><div class="detail-layout"><section class="detail-card"><span class="category"><?= h($event['category']) ?></span><h1><?= h($event['title']) ?></h1><p class="lead"><?= h($event['description']) ?></p><div class="detail-info"><div><small>Date</small><strong><?= h(date('d M Y',strtotime($event['event_date']))) ?></strong></div><div><small>Time</small><strong><?= h(date('g:i A',strtotime($event['event_time']))) ?></strong></div><div><small>Venue</small><strong><?= h($event['venue']) ?></strong></div><div><small>Seats remaining</small><strong><?= $remaining ?></strong></div></div></section><aside class="register-panel"><p class="eyebrow">JOIN THE EVENT</p><h2>Ready to participate?</h2><?php if(isset($_SESSION['user_id'])&&($_SESSION['role']??'')==='user'): ?><?php if($remaining>0): ?><form method="post" action="register_event.php"><?= csrf_field() ?><input type="hidden" name="event_id" value="<?= (int)$event['id'] ?>"><button class="primary-btn full" type="submit">Register Now</button></form><?php else: ?><p>This event is fully booked.</p><?php endif; ?><?php else: ?><p>Sign in with a student account to register.</p><a class="primary-btn full" href="login.php">Login to Register</a><?php endif; ?></aside></div></main><?php include 'includes/footer.php'; ?>
